super()로 부모 기능 활용하기 코드
super_ex.py
class Animal:
def __init__(self, name):
self.name = name
class Dog(Animal):
def __init__(self, name, breed):
super().__init__(name) # 부모 생성자 호출
self.breed = breed
d = Dog("초코", "푸들")
print(d.name, d.breed)

메서드 오버라이딩 코드
override.py
class Shape:
def area(self):
return 0
class Circle(Shape):
def __init__(self, r):
self.r = r
def area(self): # 부모 메서드 재정의
return 3.14 * self.r ** 2
print(Circle(3).area()) # 28.26

