추상 클래스로 규칙 강제하기 코드
abstract.py
from abc import ABC, abstractmethod
class Shape(ABC):
@abstractmethod
def area(self):
pass # 자식이 반드시 구현
class Circle(Shape):
def __init__(self, r): self.r = r
def area(self): return 3.14 * self.r ** 2
NOTE Shape 자체는 인스턴스로 만들 수 없고, area()를 구현하지 않은 자식 클래스도 만들 수 없습니다.
